-- Wandering Isle: quests that could not be completed or had no event.
-- Rows taken from the Legends-of-Azeroth-Pandaria-5.4.8 world DB (GPL v2 or later), adapted to SkyFire's columns.
-- Safe to run twice.

-- 29408 The Lesson of the Burning Scroll: nothing gave the "Snatch the Master's Flame" credit (59591).
-- On accept the player casts The Master's Flame (114610: flame in hand + credit) and gets the item, as LoA does.
DELETE FROM `smart_scripts` WHERE `entryorguid`=53566 AND `source_type`=0 AND `id` IN (9,10);

-- 29794 None Left Behind: Injured Sailors can be picked up (spellclick) and carried to Delora Lionheart.
UPDATE `creature_template` SET `npcflag`=`npcflag`|16777216 WHERE `entry`=55999;
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry`=55999;
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=18 AND `SourceGroup`=55999 AND `SourceEntry`=129340;

-- 29792 Bidden to Greatness: areatrigger at Mandori Village summons Aysa, Ji and Jojo, who open the two gates.
DELETE FROM `areatrigger_scripts` WHERE `entry`=7710;
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=22 AND `SourceGroup`=4 AND `SourceEntry`=59986 AND `SourceId`=0;

-- 29798 An Ancient Evil: Vordraka's abilities and adds (C++), Aysa helps (SmartAI below).
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_vordraka' WHERE `entry`=56009;

-- 30767 Risking It All: accepting the quest summons Aysa and Ji; the walk ends with the movie, the credit (60727) and a teleport.
-- SmartAI (rows from LoA's world DB)
UPDATE `creature_template` SET `AIName`='SmartAI', `ScriptName`='' WHERE `entry` IN (55999,59986,59988,59989,56416,60729,60741,60685,55943);
