INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(55943,0,0,'Never met them before in my life. Pandaren don\'t really come in any bad flavors though.',12,0,100,1,0,28090,'Wei Palerage'),
(55999,0,0,'I can... I can barely breathe.  I\'m alive thanks to you.',12,0,100,18,0,0,'Raufen - Injured Soldier - Talk'),
(55999,0,1,'I owe you my life.',12,0,100,2,0,0,'Raufen - Injured Soldier - Talk'),
(55999,0,2,'I thought that was it... I thought I was going to die.  Thank you, stranger.',12,0,100,18,0,0,'Raufen - Injured Soldier - Talk'),
(55999,0,3,'I\'m alive thanks only to you... I won\'t forget this.',12,0,100,18,0,0,'Raufen - Injured Soldier - Talk'),
(55999,0,4,'I\'m... alive?  Thank you... thank you so much!',12,0,100,18,0,0,'Raufen - Injured Soldier - Talk'),
(55999,0,5,'I... I am in your debt.',12,0,100,0,0,0,'Raufen - Injured Soldier - Talk'),
(55999,0,6,'Thank you for the timely rescue, hero.',12,0,100,2,0,0,'Raufen - Injured Soldier - Talk'),
(56416,0,0,'Thank Shen-zin Su that you\'re here.  I could use your help!',12,0,100,0,0,27384,'Aysa Cloudsinger'),
(56416,1,0,'Get clear when it when it raises its weapon, it\'s even stronger than it looks.',12,0,100,0,0,27385,'Aysa Cloudsinger'),
(56416,2,0,'It\'s calling allies!  I\'ll keep him busy while you handle them.',12,0,100,0,0,27386,'Aysa Cloudsinger'),
(56416,3,0,'We\'re wearing him down.  Keep it up!',12,0,100,0,0,27387,'Aysa Cloudsinger'),
(56416,4,0,'I don\'t know what I would have done without you.  It\'s good that you came.',12,0,100,0,0,27388,'Aysa Cloudsinger'),
(59986,0,0,'$n\'s here. Let\'s go.',12,0,100,432,0,27420,'Aysa Cloudsinger'),
(59986,1,0,'Wha...',12,0,100,432,0,27421,'Aysa Cloudsinger'),
(59986,2,0,'The gate is jammed.',12,0,100,274,0,27422,'Aysa Cloudsinger'),
(59986,3,0,'The Alliance? If the crashed ship is theirs, we need to contact them. Jojo, would you come with me?',12,0,100,6,0,27419,'Aysa Cloudsinger'),
(59988,0,0,'Let me try.',12,0,100,5,0,27339,'Ji Firepaw'),
(59988,1,0,'Did they prop this door up against a boulder?  It won\'t budge!',12,0,100,5,0,27340,'Ji Firepaw'),
(59988,2,0,'Well done, Jojo!',12,0,100,0,0,27341,'Ji Firepaw'),
(59988,3,0,'We need to dislodge that ship, Korga.  If we help your crewmates, can you help us?',12,0,100,1,0,27333,'Ji Firepaw'),
(59988,4,0,'Well, we\'ve got a master person-finder here, eh $p?  We\'re on it.',12,0,100,1,0,27334,'Ji Firepaw'),
(60042,0,0,'Wei, are these friends of yours?',12,0,100,6,0,28120,'Korga Strongmane'),
(60042,1,0,'Korga Strongmane, once prisoner of the Alliance, now free and woefully unarmed tauren. Good to meet you, pandaren.',12,0,100,66,0,28121,'Korga Strongmane'),
(60042,2,0,'Gladly, my new friend. Our engineer is still in the wilds though - we\'ll need to rescue him first.',12,0,100,1,0,28122,'Korga Strongmane'),
(60729,0,0,'Ji may kill Shen-zin Su if we let him go through with this! Come with me, $p, quickly!',12,0,100,5,0,27412,'Aysa Cloudsinger'),
(60729,1,0,'Ji, stop! This is reckless and stupid.',12,0,100,5,0,27413,'Aysa Cloudsinger'),
(60729,2,0,'If you stop this, then maybe we can come up with one.',12,0,100,274,0,27414,'Aysa Cloudsinger'),
(60729,3,0,'Doing THIS risks everything!',12,0,100,5,0,27415,'Aysa Cloudsinger'),
(60729,4,0,'Ji... if this is what you must do, I will not stop you, but we could lose everything. I hope you\'re right.',12,0,100,1,0,27416,'Aysa Cloudsinger'),
(60729,5,0,'Aysa sighs.',16,0,100,274,0,0,'Aysa Cloudsinger'),
(60741,0,0,'Aysa, this is our only option. We blow the ship free, then we heal his wound. We have no other solution.',12,0,100,1,0,27329,'Ji Firepaw'),
(60741,1,0,'So we just wait until we think of something? Shen-zin Su is dying! Doing nothing risks everything!',12,0,100,6,0,27330,'Ji Firepaw'),
(60741,2,0,'I\'d rather die knowing that at least we tried.',12,0,100,1,0,27331,'Ji Firepaw');
